 init(c,30);c.players.slice(2).forEach(p=>{p.visible=false;p.alive=false;});const tiles=Array.from({length:64},(_,i)=>({x:(i%8-3.5)*1.4,z:(Math.floor(i/8)-3.5)*1.4,owner:-1})),warps=[{x:-4.9,z:-4.9},{x:4.9,z:4.9},{x:4.9,z:-4.9},{x:-4.9,z:4.9}];c.players.slice(0,2).forEach((p,i)=>{p.x=i?3:-3;p.z=i?3:-3;p.warp=0;p.botRow=i?7:0;p.botCol=i?7:0;});
